export interface PaymentNetwork {
  code: string;
  icon: string;
  label: string;
}

export interface CurrencyConfig {
  currency: string;
  display: string;
  icon: string;
  networks?: PaymentNetwork[];
}

export const AVAILABLE_CURRENCIES: CurrencyConfig[] = [
  {
    currency: "INR",
    display: "Indian Rupee",
    icon: "currency_rupee",
    networks: [
      { code: "BANK", icon: "account_balance", label: "BANK" },
      { code: "UPI", icon: "qr_code_scanner", label: "UPI" },
    ],
  },
  {
    currency: "USDT",
    display: "Tether",
    icon: "toll",
    networks: [
      { code: "ERC20", icon: "hub", label: "ERC20" },
      { code: "BEP20", icon: "lan", label: "BEP20" },
      { code: "TRC20", icon: "settings_ethernet", label: "TRC20" },
      { code: "OMNI", icon: "currency_bitcoin", label: "OMNI" },
      { code: "SPL", icon: "token", label: "SPL" },
    ],
  },
];

export const CURRENCY_MAP: Map<string, CurrencyConfig> = new Map(
  AVAILABLE_CURRENCIES.map((c) => [c.currency, c]),
);

export const getCurrency = (code: string): CurrencyConfig | undefined =>
  CURRENCY_MAP.get(code);

export const getNetworks = (code: string): PaymentNetwork[] =>
  CURRENCY_MAP.get(code)?.networks ?? [];

export const getNetwork = (
  currencyCode: string,
  networkCode: string,
): PaymentNetwork | undefined =>
  getNetworks(currencyCode).find((n) => n.code === networkCode);

export interface ExistingCurrencyData {
  rate: number | null;
  effectiveFrom: any;
  modes: string[];
}

export type ExistingDataMap = Record<string, ExistingCurrencyData | null>;

export const buildEmptyExistingData = (): ExistingDataMap =>
  Object.fromEntries(AVAILABLE_CURRENCIES.map((c) => [c.currency, null]));



